(async () => {
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
  const setV = (el, v) => { const d = Object.getOwnPropertyDescriptor(Object.getPrototypeOf(el), 'value').set; d.call(el, v); el.dispatchEvent(new Event('input', { bubbles: true })); };
  const out = { steps: [] };
  try {
    // ① 建一个卍解作品
    const nameInput = document.querySelector('.tb-card .tb-input');
    if (!nameInput) { out.error = '新建面板没打开'; return JSON.stringify(out); }
    setV(nameInput, '边界测试·超大代码');
    [...document.querySelectorAll('.tb-diff-opt')].find((b) => b.textContent.includes('卍解'))?.click();
    await sleep(300);
    [...document.querySelectorAll('.tb-btn-primary')].find((b) => b.textContent.includes('创建'))?.click();
    for (let i = 0; i < 20; i++) { await sleep(500); if (document.querySelector('.pc-wrap')) break; }
    out.projectOpened = !!document.querySelector('.pc-wrap');

    // ② 页面内造一个 260KB 的代码文件（超过 200KB 上限）喂给文件框
    const big = '// ' + 'x'.repeat(260 * 1024) + '\nint main(void){return 0;}\n';
    out.fileBytes = big.length;
    const input = document.querySelector('.pc-wrap input[type=file]');
    out.inputFound = !!input;
    if (!input) return JSON.stringify(out);
    const dt = new DataTransfer();
    dt.items.add(new File([big], 'huge.c', { type: 'text/plain' }));
    input.files = dt.files;
    input.dispatchEvent(new Event('change', { bubbles: true }));
    for (let i = 0; i < 16; i++) { await sleep(400); if (document.querySelector('.pc-msg')) break; }

    out.hint = document.querySelector('.pc-msg')?.textContent || null;
    out.editorOpened = !!document.querySelector('.pc-textarea');
    out.savedFiles = document.querySelectorAll('.pc-item-name').length;

    // ③ 再造一个刚好在限额内的文件，确认正常路径没被误伤
    const ok = '// ' + 'y'.repeat(1000) + '\nint main(void){return 0;}\n';
    const dt2 = new DataTransfer();
    dt2.items.add(new File([ok], 'small.c', { type: 'text/plain' }));
    input.files = dt2.files;
    input.dispatchEvent(new Event('change', { bubbles: true }));
    await sleep(1200);
    const btn = [...document.querySelectorAll('.pc-btn-primary')].find((b) => b.textContent.includes('放进作品'));
    out.smallAccepted = !!btn;
    btn?.click();
    await sleep(2000);
    out.savedAfterSmall = [...document.querySelectorAll('.pc-item-name')].map((e) => e.textContent);
  } catch (e) {
    out.error = String(e && e.message ? e.message : e);
  }
  return JSON.stringify(out);
})()
